<template><div class="app-container p-4"><h2>AI 资源管理</h2><el-tabs v-model="scope" @tab-change="page=1;load()"><el-tab-pane label="企业资源" name="enterprise"/><el-tab-pane label="安全治理元数据" name="govern"/></el-tabs><p>{{scope==='enterprise'?'创建、维护企业资源；发布需要明确提交并审核。':'私人资源只展示运行治理元数据，不显示名称、配置或正文。'}}</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-if="scope==='enterprise'" class="toolbar"><el-select v-model="type" aria-label="资源类型" @change="page=1;load()"><el-option v-for="(label,key) in types" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="edit()">新建企业{{types[type]}}</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column v-if="scope==='enterprise'" prop="name" label="名称"/><el-table-column v-else prop="id" label="资源 ID"/><el-table-column label="类型"><template #default="{row}">{{types[row.resourceType]}}</template></el-table-column><el-table-column prop="ownerType" label="所有者类型"/><el-table-column v-if="scope==='enterprise'" prop="version" label="最新版本"/><el-table-column v-if="scope==='enterprise'" prop="visibility" label="范围"/><el-table-column label="状态"><template #default="{row}">{{row.securityDisabled?'安全停用':row.enabled?'已启用':'已停用'}}</template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{row}"><template v-if="scope==='enterprise'"><el-button link @click="edit(row.id)">编辑</el-button><el-button link :disabled="row.visibility==='ENTERPRISE_PUBLIC'" @click="act(()=>api('/ai/resources/'+row.id+'/activate',{version:row.version}))">启用版本</el-button><el-button link @click="publish(row)">提交审核</el-button><el-button link @click="openShares(row)">共享授权</el-button><el-button v-if="row.resourceType==='KNOWLEDGE'" link @click="openDocuments(row)">文档</el-button><el-button v-if="row.resourceType==='MCP'" link :disabled="!row.publishedVersion" @click="openConnection(row)">企业连接</el-button><el-button link @click="act(()=>api('/ai/resources/'+row.id+'/enabled',{enabled:!row.enabled},'put'))">{{row.enabled?'停用':'启用'}}</el-button><el-button v-if="row.visibility==='ENTERPRISE_PUBLIC'" link @click="withdraw(row)">撤回发布</el-button></template><el-button v-else link @click="govern(row)">{{row.securityDisabled?'解除安全停用':'安全停用'}}</el-button></template></el-table-column></el-table><div class="mt-4"><el-button :disabled="page===1||loading" @click="page--;load()">上一页</el-button>第 {{page}} 页<el-button :disabled="rows.length<30||loading" @click="page++;load()">下一页</el-button></div>
 <el-dialog v-model="dialog" :title="(editing?'编辑':'新建')+'企业'+types[type]" width="750px"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" maxlength="500"/></el-form-item><template v-if="type==='ASSISTANT'"><el-form-item label="头像符号"><el-input v-model="form.avatar" maxlength="12"/></el-form-item><el-form-item label="授权模型"><el-select v-model="form.modelId" aria-label="授权模型"><el-option v-for="m in models" :key="m.id" :label="m.name" :value="m.id"/></el-select></el-form-item><el-form-item label="助手指令"><el-input v-model="form.instruction" type="textarea" :rows="5" maxlength="4000"/></el-form-item><el-form-item v-for="kind in dependencyKinds" :key="kind.type" :label="kind.label"><el-select v-model="form[kind.key]" multiple :multiple-limit="kind.type==='TOOL'?16:8" :aria-label="kind.label"><el-option v-for="r in choices[kind.type]||[]" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item></template><template v-else-if="type==='SKILL'"><el-form-item label="导入 SKILL.md"><input type="file" accept=".md" @change="importSkill"/></el-form-item><el-form-item label="技能原文"><el-input v-model="form.source" type="textarea" :rows="12" maxlength="24000"/></el-form-item></template><template v-else-if="type==='TOOL'"><el-form-item label="允许的工具类型"><el-select v-model="form.toolType" aria-label="允许的工具类型"><el-option v-for="t in toolTypes" :key="t.code" :value="t.code" :label="t.name"/></el-select></el-form-item><el-form-item v-if="form.toolType==='CALCULATOR'" label="除法小数位"><el-input-number v-model="form.precision" :min="0" :max="8"/></el-form-item></template><template v-else-if="type==='MCP'"><el-form-item label="服务类型"><el-select v-model="form.managedProfile"><el-option label="公网 HTTPS" value=""/><el-option label="本地验收目录（合成数据）" value="acceptance-catalog"/></el-select></el-form-item><el-form-item v-if="!form.managedProfile" label="MCP HTTPS 地址"><el-input v-model="form.endpoint"/></el-form-item><el-form-item label="认证类型"><el-select v-model="form.authType"><el-option label="Bearer 密钥" value="BEARER"/><el-option v-if="!form.managedProfile" label="无认证" value="NONE"/></el-select></el-form-item><el-form-item label="允许调用的工具（英文逗号分隔）"><el-input v-model="form.allowedTools"/></el-form-item><p>仅支持 Streamable HTTP。公网地址须由服务端列入 workspace.mcp.allowed-hosts；先发布模板，再配置并测试企业连接。密钥只保存在服务端。</p></template><p v-else>支持 UTF-8 txt/md/csv/json。保存后进入文档管理上传和索引。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存企业资源</el-button></template></el-dialog>
 <el-dialog v-model="documentsVisible" title="企业知识文档" width="850px"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="selected"><p>{{selected.name}} · UTF-8 文本，最大 2 MiB。更新后需重新提交发布审核。</p><input aria-label="上传企业知识文档" type="file" accept=".txt,.md,.csv,.json" :disabled="busy" @change="uploadDocument"/><el-button @click="loadDocuments">刷新索引状态</el-button><el-table :data="documents"><el-table-column prop="title" label="文件"/><el-table-column prop="version" label="版本"/><el-table-column label="索引状态"><template #default="{row}">{{statuses[row.status]||row.status}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="previewDocument(row)">预览</el-button><input type="file" accept=".txt,.md,.csv,.json" :aria-label="'更新 '+row.title" :disabled="busy" @change="uploadDocument($event,row)"/><el-button link @click="reindex(row.id)">重新索引</el-button><el-button link @click="removeDocument(row.id)">删除</el-button></template></el-table-column></el-table><el-button :disabled="documentPage===1" @click="documentPage--;loadDocuments()">上一页文档</el-button><span>第 {{documentPage}} 页</span><el-button :disabled="documents.length<30" @click="documentPage++;loadDocuments()">下一页文档</el-button><pre class="source">{{source}}</pre></template></el-dialog>
 <el-dialog v-model="connectionVisible" title="企业 MCP 连接" width="650px"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert title="凭据仅用于企业连接，不会随模板或助手共享。员工仍需模板 USE 权限。" type="info" :closable="false"/><p>{{statuses[connection?.status]||'尚未配置'}} · {{connection?.secretConfigured?'已配置密钥':'未配置密钥'}}</p><el-input v-model="secret" type="password" autocomplete="new-password" placeholder="输入新密钥；留空保留已有值"/><el-switch v-model="connectionEnabled" active-text="启用连接"/><div class="mt-4"><el-button :loading="busy" @click="saveConnection">保存并绑定当前模板版本</el-button><el-button :disabled="!connection||busy" @click="testConnection">测试与发现工具</el-button></div><el-table :data="connection?.tools||[]"><el-table-column prop="name" label="工具名称"/><el-table-column prop="description" label="说明"/></el-table></el-dialog>
 <el-dialog v-model="sharesVisible" title="企业资源共享" width="750px"><el-alert v-if="error" :title="error" type="error" :closable="false"/><p>按引用授权，依赖和连接凭据不自动继承。撤回一条分享后，其它公开、部门或角色授权仍然适用。</p><el-select v-model="targetType" @change="targets=[];targetId=''" aria-label="分享对象类型"><el-option label="员工" value="USER"/><el-option label="部门" value="DEPARTMENT"/><el-option label="角色" value="ROLE"/></el-select><el-input v-model="targetQuery" :placeholder="targetType==='USER'?'搜索员工昵称或登录账号，至少两个字符':'搜索对象名称，至少两个字符'"/><el-button :disabled="targetQuery.length<2||busy" @click="findTargets">查找对象</el-button><el-select v-model="targetId" aria-label="选择分享对象"><el-option v-for="t in targets" :key="t.id" :value="t.id" :label="t.name+' · '+t.id"/></el-select><el-checkbox v-model="shareUse">允许使用</el-checkbox><el-checkbox v-model="shareEdit">允许编辑草稿</el-checkbox><el-button :disabled="!targetId||busy" @click="grantShare">确认分享</el-button><el-table :data="shareRows"><el-table-column prop="name" label="对象"/><el-table-column prop="actions" label="动作"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='ACTIVE'" @click="revokeShare(row.id)">撤回分享</el-button></template></el-table-column></el-table></el-dialog>
 </div></template>
<script setup lang="ts">
import request from '@/utils/request';
const statuses:Record<string,string>={READY:'可使用',QUEUED:'等待索引',RUNNING:'索引中',COMPLETED:'已完成',FAILED:'失败',ERROR:'失败',NOT_TESTED:'尚未测试'};
const types:Record<string,string>={ASSISTANT:'助手',SKILL:'技能',MCP:'MCP',TOOL:'工具',KNOWLEDGE:'知识库'},type=ref('ASSISTANT'),scope=ref('enterprise'),rows=ref<any[]>([]),page=ref(1),loading=ref(true),error=ref(''),busy=ref(false),dialog=ref(false),editing=ref<any>(),form=ref<any>({}),models=ref<any[]>([]),choices=ref<Record<string,any[]>>({}),toolTypes=ref<any[]>([]),selected=ref<any>(),documentsVisible=ref(false),documents=ref<any[]>([]),source=ref(''),connectionVisible=ref(false),connection=ref<any>(),secret=ref(''),connectionEnabled=ref(true);
const documentPage=ref(1),sharesVisible=ref(false),shareRows=ref<any[]>([]),targetType=ref('USER'),targetQuery=ref(''),targets=ref<any[]>([]),targetId=ref(''),shareUse=ref(true),shareEdit=ref(false);
const dependencyKinds=[{type:'SKILL',key:'skillIds',label:'绑定技能'},{type:'MCP',key:'mcpIds',label:'绑定 MCP'},{type:'TOOL',key:'toolIds',label:'绑定工具'},{type:'KNOWLEDGE',key:'knowledgeIds',label:'绑定知识'}];
async function api(url:string,data?:unknown,method=data?'post':'get'){return(await request({url,method,data,headers:data instanceof FormData?{repeatSubmit:false}:{}})).data;}
async function load(){loading.value=true;error.value='';try{rows.value=await api(scope.value==='govern'?'/ai/govern/resources?page='+page.value:'/ai/resources?scope=enterprise&type='+type.value+'&page='+page.value);}catch{error.value='资源加载失败，请刷新重试。';}finally{loading.value=false;}}
async function act(fn:()=>Promise<unknown>){busy.value=true;error.value='';try{await fn();await load();}catch{error.value='操作未完成，请核对资源版本、启用状态及权限。';}finally{busy.value=false;}}
async function edit(id?:string){await act(async()=>{editing.value=id?await api('/ai/resources/'+id):null;const c=editing.value?.config||{};form.value={name:editing.value?.name||'',description:editing.value?.description||'',avatar:c.avatar||'✦',instruction:c.instruction||'根据已授权资料和工具完成任务。',modelId:c.modelId||'',skillIds:c.skillIds||[],mcpIds:c.mcpIds||[],toolIds:c.toolIds||[],knowledgeIds:c.knowledgeIds||[],source:c.source||'---\nname: enterprise-method\ndescription: 企业工作方法\nversion: 1.0.0\nrequiredTools: []\ndependencies: []\n---\n请清晰区分结论和依据。',toolType:c.toolType||'CALCULATOR',precision:c.precision??4,managedProfile:c.managedProfile||'',endpoint:c.endpoint||'',authType:c.authType||'BEARER',allowedTools:(c.allowedTools||['search']).join(', ')};if(type.value==='ASSISTANT'){models.value=await api('/ai/models/available');for(const kind of dependencyKinds){const groups=await Promise.all(['enterprise','public'].map(s=>api('/ai/resources?scope='+s+'&type='+kind.type)));choices.value[kind.type]=[...new Map(groups.flat().filter(r=>r.actions.includes('USE')).map(r=>[r.id,r])).values()];}}if(type.value==='TOOL')toolTypes.value=await api('/ai/tool-types');dialog.value=true;});}
async function importSkill(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file&&file.size<=48000)form.value.source=await file.text();else error.value='技能文件过大或不可读取。';}
async function save(){if(!form.value.name.trim()){error.value='请填写名称。';return;}await act(async()=>{const f=form.value;const config=type.value==='ASSISTANT'?{avatar:f.avatar,instruction:f.instruction,modelId:f.modelId,skillIds:f.skillIds,mcpIds:f.mcpIds,toolIds:f.toolIds,knowledgeIds:f.knowledgeIds}:type.value==='SKILL'?{source:f.source}:type.value==='TOOL'?{toolType:f.toolType,precision:f.precision}:type.value==='KNOWLEDGE'?{format:'TEXT_V1'}:{transport:'STREAMABLE_HTTP',...(f.managedProfile?{managedProfile:f.managedProfile}:{endpoint:f.endpoint}),authType:f.authType,allowedTools:f.allowedTools.split(',').map((s:string)=>s.trim()).filter(Boolean),timeoutSeconds:30};await api('/ai/resources'+(editing.value?'/'+editing.value.id:''),{name:f.name,description:f.description,config,...(editing.value?{expectedVersion:editing.value.version}:{resourceType:type.value,enterprise:true,idempotencyKey:crypto.randomUUID()})},editing.value?'put':'post');dialog.value=false;});}
async function publish(row:any){error.value='';try{const check=await api('/ai/resources/'+row.id+'/publication-check?version='+row.version);if(!check.ready){error.value='暂不能提交：'+check.issues.map((item:any)=>item.type+' '+item.code).join('；')+'。请先发布依赖、启用模型并测试 MCP 连接。';return;}}catch{error.value='发布校验失败，请刷新版本并检查权限。';return;}try{await ElMessageBox.confirm('将当前资源版本及知识文档快照提交审核。通过后企业员工可查看和使用，依赖权限不自动扩展。','提交企业发布');}catch{return;}await act(()=>api('/ai/resources/'+row.id+'/publication',{version:row.version}));}
async function withdraw(row:any){try{await ElMessageBox.confirm('撤回公开发布将停止相关任务，并撤回待审申请。','撤回发布');}catch{return;}await act(()=>api('/ai/resources/'+row.id+'/publication',undefined,'delete'));}
async function govern(row:any){let reason;try{reason=(await ElMessageBox.prompt('填写治理原因。此操作不授予私人内容访问权限。','资源安全治理')).value;}catch{return;}await act(()=>api('/ai/govern/resources/'+row.id+'/enabled',{enabled:row.securityDisabled,reason},'put'));}
async function openDocuments(row:any){selected.value=row;documentPage.value=1;source.value='';documentsVisible.value=true;await loadDocuments();}
async function loadDocuments(){await act(async()=>{documents.value=await api('/ai/knowledge/'+selected.value.id+'/documents?page='+documentPage.value);});}
async function uploadDocument(event:Event,doc?:any){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await act(async()=>{const data=new FormData();data.set('file',file);data.set('idempotencyKey',crypto.randomUUID());if(doc){data.set('documentId',doc.id);data.set('expectedVersion',String(doc.latest_version));}await api('/ai/knowledge/'+selected.value.id+'/documents',data);documents.value=await api('/ai/knowledge/'+selected.value.id+'/documents?page='+documentPage.value);});input.value='';}
async function previewDocument(row:any){await act(async()=>{source.value=(await api('/ai/knowledge/documents/'+row.id+'/versions/'+row.version)).content;});}
async function reindex(id:string){await act(()=>api('/ai/knowledge/documents/'+id+'/reindex',{}));await loadDocuments();}
async function removeDocument(id:string){try{await ElMessageBox.confirm('删除文档会取消相关任务并使旧引用失效。','删除文档');}catch{return;}await act(()=>api('/ai/knowledge/documents/'+id,undefined,'delete'));await loadDocuments();}
async function openConnection(row:any){selected.value=row;secret.value='';await act(async()=>{const rows=await api('/ai/mcp/connections?resourceId='+row.id);connection.value=rows.find((c:any)=>c.scope==='ENTERPRISE');connectionEnabled.value=connection.value?.enabled??true;connectionVisible.value=true;});}
async function saveConnection(){await act(async()=>{connection.value=await api('/ai/mcp/connections'+(connection.value?'/'+connection.value.id:''),{resourceId:selected.value.id,scope:'ENTERPRISE',templateVersion:selected.value.publishedVersion,secret:secret.value||null,enabled:connectionEnabled.value,...(connection.value?{expectedVersion:connection.value.version}:{})},connection.value?'put':'post');secret.value='';});}
async function testConnection(){busy.value=true;error.value='';try{const result=await api('/ai/mcp/connections/'+connection.value.id+'/tests',{});const rows=await api('/ai/mcp/connections?resourceId='+selected.value.id);connection.value=rows.find((c:any)=>c.scope==='ENTERPRISE');if(result.status==='PASS')ElMessage.success('企业 MCP 已验证，可供授权员工使用。');else error.value='连接未通过：'+(connection.value?.last_error||'请检查目的地、密钥和工具白名单。');}catch{error.value='连接测试未完成，请检查权限或网络。';}finally{busy.value=false;}}
async function openShares(row:any){selected.value=row;targetId.value='';targets.value=[];await act(async()=>{shareRows.value=await api('/ai/resources/'+row.id+'/shares');sharesVisible.value=true;});}
async function findTargets(){await act(async()=>{targets.value=await api('/ai/share-targets?type='+targetType.value+'&query='+encodeURIComponent(targetQuery.value));targetId.value='';});}
async function grantShare(){await act(async()=>{await api('/ai/resources/'+selected.value.id+'/shares',{subjectType:targetType.value,subjectId:targetId.value,actions:['VIEW',...(shareUse.value?['USE']:[]),...(shareEdit.value?['EDIT']:[])]});shareRows.value=await api('/ai/resources/'+selected.value.id+'/shares');});}
async function revokeShare(id:string){try{await ElMessageBox.confirm('撤回当前分享会停止相关任务；其它有效授权仍适用。','撤回分享');}catch{return;}await act(async()=>{await api('/ai/resources/'+selected.value.id+'/shares/'+id,undefined,'delete');shareRows.value=await api('/ai/resources/'+selected.value.id+'/shares');});}
onMounted(load);
</script>
<style scoped>.toolbar{display:flex;gap:16px;margin:16px 0}.toolbar .el-select{width:200px}.source{white-space:pre-wrap;max-height:360px;overflow:auto;padding:16px;background:#f5f7fa}</style>
